// Package postgres implements watch.Store and watch.Relay against
// PostgreSQL via jackc/pgx. The queries are generated by sqlc from
// queries.sql.
package postgres

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/pgxerr"
	"github.com/garamsh/garam/internal/watch"
	"github.com/garamsh/garam/internal/watch/postgres/db"
)

// Store implements watch.Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql; it holds no watch of its own, so
// every process reads the same count from it.
type Store struct {
	q *db.Queries
}

// Compile-time check that Store satisfies watch.Store.
var _ watch.Store = (*Store)(nil)

// New constructs a Postgres-backed watch.Store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

// Open records the watch, after dropping the ones whose leases ran out.
// A row is written here and nowhere else, so sweeping here keeps the
// table proportional to the streams that are open rather than to the
// processes that have died holding one.
func (s *Store) Open(ctx context.Context, id watch.WatchID, agent grn.GRN, lease time.Duration) error {
	if err := s.q.DeleteLapsedWatches(ctx); err != nil {
		return pgxerr.Classify(err, "sweep", nil, nil)
	}
	err := s.q.OpenWatch(ctx, db.OpenWatchParams{
		ID:       string(id),
		AgentGrn: agent.String(),
		Lease:    interval(lease),
	})
	if err != nil {
		return pgxerr.Classify(err, "open", nil, nil)
	}
	return nil
}

// Refresh carries a live watch's lease forward.
func (s *Store) Refresh(ctx context.Context, id watch.WatchID, lease time.Duration) error {
	rows, err := s.q.RefreshWatch(ctx, db.RefreshWatchParams{ID: string(id), Lease: interval(lease)})
	if err != nil {
		return pgxerr.Classify(err, "refresh", nil, nil)
	}
	if rows == 0 {
		return watch.ErrWatchLapsed
	}
	return nil
}

// Close deletes the watch's lease.
func (s *Store) Close(ctx context.Context, id watch.WatchID) error {
	if err := s.q.CloseWatch(ctx, string(id)); err != nil {
		return pgxerr.Classify(err, "close", nil, nil)
	}
	return nil
}

// Count reports how many watches on the agent are live.
func (s *Store) Count(ctx context.Context, agent grn.GRN) (int, error) {
	count, err := s.q.CountLiveWatches(ctx, agent.String())
	if err != nil {
		return 0, pgxerr.Classify(err, "count", nil, nil)
	}
	return int(count), nil
}

// interval converts a duration to the Postgres interval a lease travels
// as.
func interval(d time.Duration) pgtype.Interval {
	return pgtype.Interval{Microseconds: d.Microseconds(), Valid: true}
}
